"""Blocks of the peripheral window (0x1001_0000, 64 KB): the address decode and read mux, and the register files of the GPIO, the SPI master and the
I2C master (the last two wrap the curated barg_spi_master and barg_i2c_master). Generated by BARG against hand-written golden models
(golden/<name>.py), never shown to the generator. Devices: GPIO at offset 0x000, SPI at 0x100, I2C at 0x200."""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent.parent / "gpu-soc"))
from build_gpu_soc import block, i, o, port  # noqa: E402

W = 32
CLK = port("p_clk", "clk", "in", 1, "clock")
RST = port("p_rst", "rst", "in", 1, "reset")

PDEV_BUS = block("b_pdev_bus", "pdev_bus", """
    Combinational. The device decode and read multiplexer of the peripheral window. pa (32 bits) is the access address and pw (1 bit) says a write is
    happening. The device is chosen by bits 11:8 of pa: 0 is the GPIO, 1 is the SPI master, 2 is the I2C master, anything else is no device. gpio_we is 1 when
    pw is 1 and the device is the GPIO; spi_we is 1 when pw is 1 and the device is the SPI master; i2c_we likewise for the I2C master; otherwise each is 0.
    prdata (32 bits) is gpio_rdata, spi_rdata or i2c_rdata (each 32 bits) for the chosen device, and 0 when no device is chosen. No clock, no reset, no state.
""", [i("pa", W, "data"), i("pw", 1, "control"), i("gpio_rdata", W, "data"), i("spi_rdata", W, "data"), i("i2c_rdata", W, "data"), o("gpio_we", 1, "control"),
      o("spi_we", 1, "control"), o("i2c_we", 1, "control"), o("prdata", W, "data")])

GPIO_REGS = block("b_gpio_regs", "gpio_regs", """
    The registers of a 16-pin GPIO. Held state: out (16 bits), oe (16 bits), ien (16 bits), pend (16 bits), and three 16-bit registers s1, s2 and prev that
    sample the input pins; all are 0 at reset. Each rising clock edge after reset: s1 becomes pins, s2 becomes s1 (held before the edge) and prev becomes s2
    (held before the edge). rise is s2 AND NOT prev (held values, a pin that went from 0 to 1 in the synchronised signal). pend becomes (pend AND NOT clr) OR
    rise, where clr is wdata bits 15:0 when we is 1 and bits 3:2 of addr are 3 and 0 otherwise. When we is 1, bits 3:2 of addr choose a register to write
    with the low 16 bits of wdata: 0 is out, 1 is oe, 2 is ien, 3 is the write-one-to-clear of pend described above. rdata (32 bits, combinational on addr
    and the held state, whether or not we is 1) by bits 3:2 of addr: 0 is s2 in the low 16 bits, 1 is oe, 2 is ien, 3 is pend, each zero-extended to 32 bits.
    gpio_out is out and gpio_oe is oe (held values). irq is 1 when pend AND ien is not zero. Reset is synchronous and has priority.
""", [CLK, RST, i("we", 1, "control"), i("addr", W, "addr"), i("wdata", W, "data"), i("pins", 16, "data"), o("rdata", W, "data"), o("gpio_out", 16, "data"),
      o("gpio_oe", 16, "data"), o("irq", 1, "control")], reset="sync", latency=1)

SPI_REGS = block("b_spi_regs", "spi_regs", """
    The registers of an SPI master that moves one 8-bit word per transfer, between the bus and the master's word interface. Held state, all 0 at reset: cs (2
    bits, the chip select chosen), last (8 bits, the last word received), done (1 bit), busy (1 bit), ien (1 bit). tx_cs is cs, tx_data is bits 7:0 of wdata, and
    tx_valid is 1 when we is 1, bits 4:2 of addr are 0 and tx_ready is 1 (a write of the word register starts a transfer when the master is ready, and is
    ignored otherwise). Each rising clock edge after reset: when tx_valid is 1, busy becomes 1; when rx_valid is 1 (the master finished a transfer), busy
    becomes 0, done becomes 1 and last becomes rx_data (rx_valid has priority over tx_valid for busy and over a clear for done). Independently of rx_valid and tx_valid, in every
    cycle: when we is 1 and bits 4:2 of addr are 2, cs becomes bits 1:0 of wdata; when we is 1 and bits 4:2 are 3, ien becomes bit 0 of wdata. In a cycle where rx_valid
    is 0, when we is 1 and bits 4:2 of addr are 1 and bit 1 of wdata is 1, done becomes 0. rdata (32 bits, combinational on addr and the held state) by bits 4:2 of addr: value 0: {24'b0, last}; value 1 (the status word): {30'b0, done, busy},
    so bit 0 is busy and bit 1 is done; value 2: {30'b0, cs}; value 3: {31'b0, ien}; any other value: 0. A write of 1 to bit 1 clears done only in a cycle where rx_valid is 0. irq is 1 when done AND ien. Reset is synchronous and has priority.
""", [CLK, RST, i("we", 1, "control"), i("addr", W, "addr"), i("wdata", W, "data"), i("tx_ready", 1, "control"), i("rx_data", 8, "data"),
      i("rx_valid", 1, "control"), o("rdata", W, "data"), o("tx_data", 8, "data"), o("tx_cs", 2, "control"), o("tx_valid", 1, "control"),
      o("irq", 1, "control")], reset="sync", latency=1)

I2C_REGS = block("b_i2c_regs", "i2c_regs", """
    The registers of an I2C master that does one byte per command, between the bus and the master's command interface. Held state, all 0 at reset: last (8 bits,
    the byte of the last response), done, busy, nack, arb and ien (1 bit each). A write of the command register (we is 1 and bits 4:2 of addr are 0) with
    cmd_ready 1 gives cmd_valid 1; cmd_data is bits 7:0 of wdata, cmd_start is bit 8, cmd_stop is bit 9, cmd_nack is bit 10 and cmd_op is bits 12:11. cmd_valid is
    0 when cmd_ready is 0 (the write is then ignored) or no such write happens. Each rising clock edge after reset: when cmd_valid is 1, busy becomes 1; when
    rsp_valid is 1, busy becomes 0, done becomes 1, last becomes rsp_data, nack becomes rsp_nack and arb becomes rsp_arb_lost (rsp_valid has priority over
    cmd_valid for busy and over a clear). Independently of rsp_valid and cmd_valid, in every cycle: when we is 1 and bits 4:2 of addr are 3, ien becomes bit 0 of wdata.
    In a cycle where rsp_valid is 0, when we is 1 and bits 4:2 of addr are 1 and bit 1 of wdata is 1, done, nack and arb become 0. rdata (32 bits, combinational on addr and the held state) by bits 4:2 of addr: value 0: {24'b0, last}; value 1 (the status word):
    {28'b0, arb, nack, done, busy}, so bit 0 is busy, bit 1 is done, bit 2 is nack and bit 3 is arb; value 2: 0; value 3: {31'b0, ien}; any other value: 0. A clear write
    (bit 1 of wdata set with bits 4:2 of addr equal to 1) has no effect in a cycle where rsp_valid is 1. irq is 1 when done AND ien. Reset is synchronous and has priority.
""", [CLK, RST, i("we", 1, "control"), i("addr", W, "addr"), i("wdata", W, "data"), i("cmd_ready", 1, "control"), i("rsp_valid", 1, "control"),
      i("rsp_data", 8, "data"), i("rsp_nack", 1, "control"), i("rsp_arb_lost", 1, "control"), o("rdata", W, "data"), o("cmd_valid", 1, "control"),
      o("cmd_op", 2, "control"), o("cmd_start", 1, "control"), o("cmd_stop", 1, "control"), o("cmd_nack", 1, "control"), o("cmd_data", 8, "data"),
      o("irq", 1, "control")], reset="sync", latency=1)

BLOCKS = [PDEV_BUS, GPIO_REGS, SPI_REGS, I2C_REGS]
